def icon(name):return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="{icons[name]}"/></svg>'
def buttons(left,right,danger=False):
 return f'<div class="actions"><button class="secondary">{left}</button><button class="{"danger" if danger else "primary"}">{right}</button></div>' if left else f'<div class="actions"><button class="primary">{right}</button></div>'
def dialog(name,title,body,footer,extra='',danger=False):
 return f'<div class="dialog"><div class="badge {"red" if danger else ""}">{icon(name)}</div><h2>{title}</h2><p>{body}</p>{extra}{footer}</div>'
def stage(n,label,dialog,sub):return f'<section class="specimen"><div class="sample-heading"><span>{n}</span>{label}</div><div class="stage"><div class="ghost g1"></div><div class="ghost g2"></div><div class="ghost g3"></div><div class="veil"></div>{dialog}</div><p class="caption">{sub}</p></section>'
common=[
 stage('01','删除扫描记录',dialog('trash','删除这条扫描记录？','这条记录及暂存素材将被删除。<br>已保存到下载目录的文件不受影响。',buttons('保留记录','删除记录',True),danger=True),'明确删除对象；红色只用于不可撤销操作。'),
 stage('02','批量取消收藏',dialog('heart','取消收藏这 6 项？','选中素材将从收藏夹移除。<br>扫描记录和已保存的文件仍会保留。',buttons('保留收藏','取消收藏',True),danger=True),'保留“收藏”语义，避免使用“删除素材”。'),
 stage('03','扫描异常暂停',dialog('pause','扫描暂时中断','当前页多次读取失败。<br>已提取素材已保留，可从当前页继续。',buttons('稍后再试','继续扫描'),'<div class="note"><span class="dot"></span>已读 344 条评论 · 已提取 66 个素材</div>'),'展示已有成果；不给出未经确认的失败原因。'),
 stage('04','部分保存失败',dialog('save','有 3 项未保存','已保存 21 项，另有 3 项未能写入。<br>素材仍在本机，可稍后重新保存。',buttons('','知道了'),'<div class="summary"><span>保存成功<strong>21 项</strong></span><span class="warn">保存失败<strong>3 项</strong></span></div>'),'标题说清结果，成功与失败分开，原因按实际返回。'),
 stage('05','备份导入失败',dialog('file','无法导入这个备份','备份文件不完整，缺少部分素材。<br>请重新选择完整的备份文件。',buttons('取消','重新选择'),'<div class="note">本机现有记录未被覆盖</div>'),'失败原因可替换；不把技术异常直接作为标题。'),
 stage('06','网页相机授权',dialog('camera','允许网页使用相机？','当前网页请求使用相机进行身份验证。',buttons('暂不允许','允许使用'),'<div class="origin"><span>请求方</span><strong>www.douyin.com</strong></div>'),'显示实际请求域名；系统权限窗口沿用系统样式。')
]
details=dialog('detail','扫描明细','查看已读取的评论与本次异常。',buttons('关闭','重试失败项'),'''<div class="stats"><span><b>195</b>主评论</span><span><b>149</b>回复</span><span><b>66</b>素材</span></div><div class="section-label">待处理<span>2 项</span></div><div class="issue"><i class="dot"></i><div><b>1 个素材下载失败</b><small>连接中断，可重试获取</small></div></div><div class="issue"><i class="dot"></i><div><b>1 组回复读取中断</b><small>已保留此前读取的结果</small></div></div><div class="section-label">异常记录<span>最近 2 条</span></div><div class="log">14:46　回复接口未返回评论数据<br>14:45　素材下载连接中断</div>''')
