extra=''.join([stage('10','等待状态',wait,'不展示虚假百分比；仅在不可打断的短任务中阻挡操作。'),stage('11','关于咻咿',about,'内容分组呈现，不再堆叠为一整段说明。')])
css='''@font-face{font-family:Noto;src:url('../home-blue-v2/assets/NotoSansSC.ttf');font-weight:100 900}*{box-sizing:border-box}body{margin:0;background:#edf1f8;color:#10192c;font-family:Noto,'Microsoft YaHei',sans-serif;--page:#f4f6fa;--surface:#fff;--ink:#10192c;--muted:#606c80;--line:#e0e6f1;--track:#f3f5fa;--blue:#456bff;--soft:#edf1ff;--danger:#d94855;--danger-soft:#fff0f1;--shadow:0 20px 50px #10234722}body.dark{background:#080e19;color:#f3f6ff;--page:#111a2a;--surface:#1a2436;--ink:#f3f6ff;--muted:#bec9dc;--line:#303e55;--track:#222f45;--blue:#708cff;--soft:#27365c;--danger:#ff8290;--danger-soft:#422b3b;--shadow:0 20px 50px #0008}header{display:flex;align-items:center;gap:18px;padding:32px 40px 20px}header h1{font-size:29px;font-weight:800;margin:0;letter-spacing:-.8px}header .mark{background:var(--blue);color:white;border-radius:15px;width:48px;height:48px;display:grid;place-items:center;font-size:25px;font-weight:800}header p{margin:4px 0 0;color:var(--muted);font-size:12px}header .meta{margin-left:auto;text-align:right;color:var(--muted);font-size:12px;line-height:1.9}.toolbar{padding:0 40px 20px;display:flex;gap:10px}.toolbar button{background:var(--surface);color:var(--ink);border:1px solid var(--line);padding:8px 15px;border-radius:20px;font:500 12px Noto;cursor:pointer}.toolbar button.selected{background:var(--blue);color:white;border-color:var(--blue)}main{padding:0 40px 20px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.sample-heading{display:flex;gap:10px;align-items:center;font-size:15px;font-weight:750;margin:0 0 10px}.sample-heading>span{font-size:10px;color:var(--blue);letter-spacing:1px;border:1px solid var(--line);background:var(--surface);border-radius:6px;padding:3px 6px}.stage{height:365px;position:relative;overflow:hidden;border:1px solid var(--line);border-radius:22px;background:var(--page);display:flex;justify-content:center;align-items:center;padding:24px}.ghost{position:absolute;left:20px;right:20px;height:56px;border-radius:13px;background:var(--surface)}.g1{top:26px}.g2{top:100px}.g3{top:177px;height:160px}.veil{position:absolute;inset:0;background:#17233729}body.dark .veil{background:#03071466}.dialog{position:relative;width:320px;max-width:100%;padding:22px;border-radius:24px;border:1px solid var(--line);background:var(--surface);box-shadow:var(--shadow);color:var(--ink)}svg{display:block;width:24px;height:24px;flex-shrink:0}.badge{width:42px;height:42px;display:grid;place-items:center;background:var(--soft);color:var(--blue);border-radius:14px;margin-bottom:13px}.badge.red{background:var(--danger-soft);color:var(--danger)}h2{font-size:19px;line-height:1.45;font-weight:750;margin:0 0 8px;letter-spacing:-.35px}p{font-size:13px;line-height:1.8;color:var(--muted);margin:0}button{font:650 13px Noto;cursor:pointer;border:0}.actions{display:flex;gap:10px;margin-top:22px}.actions button{min-width:0;flex:1;min-height:44px;border-radius:12px;padding:9px 8px;line-height:1.5;transition:transform .15s,opacity .15s}.actions button:active,.choice:active{transform:scale(.97)}button.primary{background:var(--blue);color:#fff}button.secondary{background:var(--track);color:var(--ink)}button.danger{background:var(--danger);color:#fff}body.dark button.danger{background:#df5869}.note{font-size:11px;line-height:1.7;padding:10px 12px;background:var(--track);border-radius:10px;color:var(--muted);margin-top:12px;display:flex;align-items:center;gap:8px}.dot{width:6px;height:6px;border-radius:50%;background:var(--blue);display:inline-block;flex-shrink:0}.summary{display:flex;margin-top:14px;padding:12px;border-radius:12px;background:var(--track)}.summary span{font-size:11px;color:var(--muted);flex:1}.summary strong{display:block;font-size:21px;font-weight:750;color:var(--ink);margin-top:2px}.summary .warn strong{color:var(--danger)}.origin{margin-top:14px;padding:11px 12px;background:var(--track);border-radius:10px;display:flex;align-items:center;justify-content:space-between;font-size:11px;gap:10px}.origin span{color:var(--muted)}.origin strong{font-weight:550}.caption{font-size:11px;line-height:1.7;margin-top:9px;min-height:36px;color:var(--muted)}.footer{margin:6px 40px 24px;display:flex;gap:16px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:16px;font-size:11px;color:var(--muted)}.footer strong{color:var(--ink);font-weight:650}.detail .stage{height:610px;padding:18px}.detail .dialog{padding:20px}.stats{display:flex;gap:6px;padding:14px 6px;background:var(--soft);border-radius:12px;margin-top:14px;text-align:center}.stats span{flex:1;font-size:11px;color:var(--muted)}.stats b{display:block;font-size:21px;color:var(--blue);font-weight:750;margin-bottom:3px}.section-label{font-size:12px;font-weight:700;display:flex;justify-content:space-between;margin-top:17px;margin-bottom:8px}.section-label span{font-size:10px;color:var(--muted);font-weight:450}.issue{display:flex;gap:9px;padding:10px 0;border-bottom:1px solid var(--line);align-items:center}.issue b{font-size:12px;font-weight:600;display:block}.issue small,.choice small{font-size:11px;line-height:1.7;color:var(--muted);display:block;margin-top:2px}.log{font-size:10px;color:var(--muted);padding:10px;border-radius:10px;background:var(--track);line-height:2}.choice{display:flex;align-items:center;gap:10px;text-align:left;background:var(--track);width:100%;padding:12px;border-radius:13px;margin-top:12px;color:var(--ink)}.choice b{font-size:13px;font-weight:650}.choice>svg:last-child{margin-left:auto;width:14px;height:14px;color:var(--muted)}.choice-icon{color:var(--blue)}.choice-icon svg{width:20px;height:20px}.preview .preview-head{display:flex;align-items:center;gap:10px;justify-content:space-between}.preview h2{margin-bottom:4px}.preview small,.about small{font-size:10px;color:var(--muted)}.icon-button{padding:4px;color:var(--muted);background:transparent}.icon-button svg{width:18px;height:18px}.image{display:grid;place-items:center;border-radius:16px;height:310px;background:var(--soft);overflow:hidden;margin-top:16px}.image img{width:94%;height:94%;object-fit:contain}.preview-actions{display:flex;gap:5px;margin-top:16px}.preview-actions button{color:var(--muted);background:var(--track);border-radius:9px;flex:1;height:46px;display:flex;align-items:center;justify-content:center;gap:4px;font-size:10px}.preview-actions svg{width:15px;height:15px}.preview-actions .highlight{background:var(--blue);color:#fff}.compact{text-align:center}.compact h2{font-size:18px}.loading{width:46px;height:46px;margin:0 auto 16px;display:grid;place-items:center;color:var(--blue);background:var(--soft);border-radius:15px}.loading svg{width:26px;height:26px}.about{text-align:center}.brand{display:grid;place-items:center;width:52px;height:52px;border-radius:16px;background:var(--blue);color:white;font-size:28px;font-weight:800;margin:0 auto 13px}.about>p{margin:12px 0 16px;font-size:12px}.about-row{text-align:left;padding:12px 0;border-top:1px solid var(--line);font-size:12px}.about-row b{display:block;margin-bottom:4px;font-weight:650}.about-row span{font-size:11px;color:var(--muted)}.extra{grid-template-columns:repeat(2,minmax(0,1fr));max-width:1000px;margin:auto}.extra .stage{height:440px}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--surface);color:var(--ink);padding:12px 20px;border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);font-size:13px;z-index:10}.hidden{display:none}body.capture .toolbar{display:none}body.capture header{padding-bottom:26px}body.capture.detail main{padding-top:0}@media(max-width:850px){.grid{grid-template-columns:1fr}header{padding:24px}.meta{display:none}main{padding:0 24px 24px}.footer{margin:0 24px 20px}.toolbar{padding:0 24px 20px;flex-wrap:wrap}}'''
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>咻咿提取 · 弹窗美术稿</title><style>'''+css+'''</style></head><body><header><div class="mark">咻</div><div><h1 id="boardTitle">统一弹窗 · 操作与反馈</h1><p>咻咿提取 / B 方向延续 · 蓝色 / 设计提案 V1</p></div><div class="meta">标题说清结果，正文说明影响<br>数值与原因均为排版示例 · 未接入 APK</div></header><nav class="toolbar"><button data-board="common">确认与失败</button><button data-board="detail">明细与预览</button><button data-board="extra">等待与关于</button><button id="theme">切换深浅色</button></nav><main><div class="grid" id="content"></div></main><div class="footer"><strong>统一规范</strong><span>宽度 ≤ 320 dp · 圆角 24 dp · 内边距 22 dp</span><span>标题 19–20 / 750 · 正文 13–14 / 400 · 按钮 13–14 / 650</span><span>按钮高 44 dp · 间距 10 dp · 无虚假进度</span></div><div id="toast" class="toast hidden"></div><script>'''+f'const boards={json.dumps({"common":"".join(common),"detail":content,"extra":extra},ensure_ascii=False)};'+'''let board=new URLSearchParams(location.search).get('board')||'common';const params=new URLSearchParams(location.search);if(params.get('theme')==='dark')document.body.classList.add('dark');if(params.has('capture'))document.body.classList.add('capture');function draw(){document.body.classList.toggle('detail',board==='detail');document.getElementById('content').className='grid '+(board==='extra'?'extra':'');document.getElementById('content').innerHTML=boards[board];document.getElementById('boardTitle').textContent={'common':'统一弹窗 · 操作与反馈','detail':'统一弹窗 · 明细与预览','extra':'统一弹窗 · 等待与关于'}[board];document.querySelectorAll('[data-board]').forEach(b=>b.classList.toggle('selected',b.dataset.board===board));document.querySelectorAll('main button').forEach(b=>b.onclick=()=>{const t=document.getElementById('toast');t.textContent='设计演示：'+b.textContent.trim();t.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.add('hidden'),2000)});document.fonts.ready.then(()=>{const overflow=[...document.querySelectorAll('main *')].filter(e=>e.scrollWidth>e.clientWidth+2&&e.clientWidth>0&&!e.matches('svg,path'));document.title='咻咿弹窗 / '+board+' / overflow='+overflow.length;})}document.querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{board=b.dataset.board;draw()});document.getElementById('theme').onclick=()=>document.body.classList.toggle('dark');draw();</script></body></html>'''
(out/'index.html').write_text(html,encoding='utf-8')
print('Created design-only boards: common / detail / extra with light and dark themes.')
